const buildScenario = (
  disasterType,
  difficulty,
  index,
  title,
  situation,
  correctAction,
  unsafeAction,
  safeFeedback,
  unsafeFeedback,
  unsafeEnding = "injured"
) => {
  const prefix = `${disasterType}-${String(index).padStart(2, "0")}`;

  return {
    title,
    disasterType,
    difficulty,
    description: situation,
    startNodeId: `${prefix}-start`,
    isActive: true,
    nodes: [
      {
        nodeId: `${prefix}-start`,
        situationText: situation,
        isEnding: false,
        options: [
          {
            optionText: correctAction,
            nextNodeId: `${prefix}-safe`,
            isCorrectChoice: true,
            feedback: safeFeedback,
          },
          {
            optionText: unsafeAction,
            nextNodeId: `${prefix}-unsafe`,
            isCorrectChoice: false,
            feedback: unsafeFeedback,
          },
        ],
      },
      {
        nodeId: `${prefix}-safe`,
        situationText: `You follow the safer response and reach the designated safe area. Continue following trained staff instructions and check in during the headcount.`,
        isEnding: true,
        endingType: "safe",
        options: [],
      },
      {
        nodeId: `${prefix}-unsafe`,
        situationText: `The unsafe response exposes you to additional danger. Stop, seek trained adult help, and contact local emergency services when appropriate.`,
        isEnding: true,
        endingType: unsafeEnding,
        options: [],
      },
    ],
  };
};

